"""Envelope encryption with a versioned key-encryption key (KEK) and a rewrap job.
Each record gets its own data key (DEK); the DEK is wrapped by the KEK version named in the record header.
Learning code: in production the KEK stays inside a KMS/HSM or OpenBao transit and never leaves it."""
import base64
import json
import os
import random

from cryptography.hazmat.primitives.ciphers.aead import AESGCM

SEED = 12  # seeds the injected fault (where the rewrap job crashes), so every run fails the same way


class UnknownKey(Exception):
    """The record names a KEK version that is not (or no longer) in the keyring."""


class KeyInUse(Exception):
    """Raised by the hardened retire() you write in the build task."""


def b64(b: bytes) -> str:
    return base64.b64encode(b).decode()


class Keyring:
    """KEK versions by number: the primary wraps new DEKs, every version still present can unwrap."""

    def __init__(self, name="orders-kek"):
        self.name, self.versions, self.primary = name, {}, 0
        self.rotate()

    def kid(self, version: int) -> str:
        return f"{self.name}:v{version}"  # key ID: written into every record header

    def rotate(self) -> str:
        self.primary += 1  # rotation = add a new version and make it primary; old versions stay
        self.versions[self.primary] = AESGCM.generate_key(bit_length=256)
        return self.kid(self.primary)

    def kek(self, kid: str) -> AESGCM:
        name, _, v = kid.rpartition(":v")
        if name != self.name or int(v) not in self.versions:
            raise UnknownKey(f"no KEK for {kid}")
        return AESGCM(self.versions[int(v)])


def wrap(ring: Keyring, dek: bytes):
    kid, n = ring.kid(ring.primary), os.urandom(12)
    return kid, b64(n + ring.kek(kid).encrypt(n, dek, kid.encode()))  # AAD = kid: a wrapped DEK cannot be relabelled


def unwrap(ring: Keyring, kid: str, wdek: str) -> bytes:
    raw = base64.b64decode(wdek)
    return ring.kek(kid).decrypt(raw[:12], raw[12:], kid.encode())


def seal(ring: Keyring, plaintext: bytes, context: str) -> dict:
    dek, n = AESGCM.generate_key(bit_length=256), os.urandom(12)  # fresh DEK per record
    kid, wdek = wrap(ring, dek)
    ct = AESGCM(dek).encrypt(n, plaintext, context.encode())  # data encrypted once, with the DEK
    return {"kid": kid, "wdek": wdek, "n": b64(n), "ct": b64(ct), "ctx": context}


def open_(ring: Keyring, rec: dict) -> bytes:
    dek = unwrap(ring, rec["kid"], rec["wdek"])
    return AESGCM(dek).decrypt(base64.b64decode(rec["n"]), base64.b64decode(rec["ct"]), rec["ctx"].encode())


def rewrap(ring: Keyring, rec: dict) -> dict:
    kid, wdek = wrap(ring, unwrap(ring, rec["kid"], rec["wdek"]))  # only the 32-byte DEK is re-encrypted
    return {**rec, "kid": kid, "wdek": wdek}  # n and ct are untouched


def count_by_kid(store: dict) -> dict:
    kids = [rec["kid"] for rec in store.values()]
    return {k: kids.count(k) for k in sorted(set(kids))}


def rewrap_job(ring: Keyring, store: dict, log=print, crash_after=None) -> int:
    target, done = ring.kid(ring.primary), 0
    for rid, rec in store.items():
        if rec["kid"] == target:  # idempotent: records already on the primary are skipped, so a rerun resumes
            continue
        if crash_after is not None and done == crash_after:
            raise RuntimeError(f"rewrap job crashed after {done} records")  # injected fault
        store[rid] = rewrap(ring, rec)
        done += 1
        log(json.dumps({"event": "rewrap", "id": rid, "from": rec["kid"], "to": target}))
    log(json.dumps({"metric": "records_by_kid", **count_by_kid(store)}))  # observability: who still needs which KEK
    return done


def retire(ring: Keyring, store: dict, version: int) -> None:
    del ring.versions[version]  # BUG on purpose: never asks whether a record still uses this version


def try_all(ring, store) -> str:
    bad = {}
    for rid, rec in store.items():
        try:
            open_(ring, rec)
        except UnknownKey as e:
            bad[rid] = str(e)
    return f"{len(store) - len(bad)}/{len(store)} decrypt" + (f"; LOST {list(bad)} ({set(bad.values())})" if bad else "")


if __name__ == "__main__":
    rng = random.Random(SEED)
    ring = Keyring()
    store = {f"order-{i}": seal(ring, f"card=4111-{rng.randrange(1000, 9999)}".encode(), f"order-{i}") for i in range(1, 7)}
    print("sealed 6 records with", ring.kid(1), "| header:", {k: store["order-1"][k] for k in ("kid", "ctx")})
    print("rotate ->", ring.rotate(), "| old records still:", try_all(ring, store))
    before = store["order-1"]["ct"]
    rewrap_job(ring, store)
    print("data ciphertext unchanged by rewrap:", store["order-1"]["ct"] == before)
    retire(ring, store, 1)
    print("retire v1 after a full rewrap:", try_all(ring, store))

    print("--- fault: rotate again, the rewrap job crashes, the operator deletes v2 anyway")
    print("rotate ->", ring.rotate())
    try:
        rewrap_job(ring, store, crash_after=rng.randrange(1, 5))  # seeded crash point
    except RuntimeError as e:
        print("job:", e, "| counts:", count_by_kid(store))
    retire(ring, store, 2)
    print("after retire v2:", try_all(ring, store))

"""Sign a release: a manifest of SHA-256 digests, signed once with Ed25519, checked by the install step.
The install step below verifies the signature but trusts the folder (the fault); the build task makes it strict."""
import base64
import hashlib
import json
import random
import shutil
import tempfile
from pathlib import Path

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey

SEED = 14
META = {"MANIFEST.json", "MANIFEST.json.sig"}


class Rejected(Exception):
    pass


def key_id(pub) -> str:
    return hashlib.sha256(pub.public_bytes_raw()).hexdigest()[:16]  # same key ID as lesson 7's keyring


def digest(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):  # stream: artifacts can be large
            h.update(chunk)
    return h.hexdigest()


def build_artifacts(dist: Path, seed=SEED) -> None:
    rng = random.Random(seed)  # seeded "build": same bytes every run
    for rel in ("app/__init__.py", "app/core.py", "app/data.json", "README.txt"):
        (dist / rel).parent.mkdir(parents=True, exist_ok=True)
        (dist / rel).write_bytes(f"# {rel} build {rng.randrange(10**6)}\n".encode() * 20)


def files_in(dist: Path) -> list:
    return sorted(p.relative_to(dist).as_posix() for p in dist.rglob("*") if p.is_file())  # '/' on Windows too


def sign_release(dist: Path, key: Ed25519PrivateKey, version: str) -> None:
    files = {rel: {"sha256": digest(dist / rel), "size": (dist / rel).stat().st_size}
             for rel in files_in(dist) if rel not in META}
    raw = json.dumps({"name": "demo-app", "version": version, "files": files}, sort_keys=True, indent=1).encode()
    (dist / "MANIFEST.json").write_bytes(raw)  # one signature covers every digest listed here
    sig = {"kid": key_id(key.public_key()), "sig": base64.b64encode(key.sign(raw)).decode()}
    (dist / "MANIFEST.json.sig").write_text(json.dumps(sig), encoding="utf-8")


def verified_manifest(dist: Path, trusted: dict) -> dict:
    raw = (dist / "MANIFEST.json").read_bytes()
    sig = json.loads((dist / "MANIFEST.json.sig").read_text(encoding="utf-8"))
    if sig["kid"] not in trusted:  # signer keyring: rotation = add the new kid, later remove the old one
        raise Rejected(f"unknown signer {sig['kid']}")
    try:
        trusted[sig["kid"]].verify(base64.b64decode(sig["sig"]), raw)  # verify the exact bytes, then parse
    except InvalidSignature:
        raise Rejected("manifest signature invalid") from None
    return json.loads(raw)


def install(dist: Path, target: Path, trusted: dict) -> list:
    """BUG on purpose: checks the signature and that listed files exist, then copies the whole folder."""
    manifest = verified_manifest(dist, trusted)
    for rel in manifest["files"]:
        if not (dist / rel).is_file():
            raise Rejected(f"missing {rel}")
    copied = [rel for rel in files_in(dist) if rel not in META]
    for rel in copied:
        (target / rel).parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(dist / rel, target / rel)
    return copied


def tamper(dist: Path, seed=SEED) -> str:
    rel = random.Random(seed).choice([r for r in files_in(dist) if r not in META])  # seeded: same victim each run
    (dist / rel).write_bytes(b"import os  # attacker payload\n")  # swap content, keep name and old manifest + sig
    (dist / "app" / "zz_extra.pth").write_bytes(b"import app.core  # auto-runs at start-up\n")  # unlisted file
    return rel


def attempt(label, dist, trusted):
    with tempfile.TemporaryDirectory() as tmp:
        try:
            print(f"{label:<28} installed {len(install(dist, Path(tmp), trusted))} files")
        except Rejected as e:
            print(f"{label:<28} REJECTED: {e}")


if __name__ == "__main__":
    signer = Ed25519PrivateKey.generate()  # CI release key; the private key never ships
    trusted = {key_id(signer.public_key()): signer.public_key()}  # what the installer pins
    with tempfile.TemporaryDirectory() as tmp:
        dist = Path(tmp)
        build_artifacts(dist)
        sign_release(dist, signer, "1.0.0")
        print("manifest lists", len(json.loads((dist / "MANIFEST.json").read_bytes())["files"]), "files; signer", key_id(signer.public_key()))
        attempt("clean release", dist, trusted)
        stranger = Ed25519PrivateKey.generate().public_key()
        attempt("installer pins another key", dist, {key_id(stranger): stranger})
        print("fault: attacker swapped", tamper(dist), "and added app/zz_extra.pth; manifest + signature unchanged")
        attempt("tampered release", dist, trusted)

"""Run Project Wycheproof-format vectors against OUR wrappers (the code we wrote around pyca/cryptography).
The library already passes; wrapper conveniences are where bugs hide. The two wrappers below are lenient on purpose."""
import json
from pathlib import Path

from cryptography.exceptions import InvalidSignature, InvalidTag
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PublicKey
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes

VECTORS = Path(__file__).resolve().parent / "vectors"
L = 2**252 + 27742317777372353535851937790883648493  # Ed25519 group order (RFC 8032)


# ---- wrappers under test: "convenient", i.e. lenient (the fault) ----
def aead_open(key: bytes, iv: bytes, ct: bytes, tag: bytes, aad: bytes) -> bytes:
    """AES-GCM open. BUG: accepts whatever tag length arrives (>= 4 bytes) instead of exactly 16."""
    dec = Cipher(algorithms.AES(key), modes.GCM(iv, tag, min_tag_length=max(4, len(tag)))).decryptor()
    dec.authenticate_additional_data(aad)
    return dec.update(ct) + dec.finalize()  # raises InvalidTag if the (possibly short) tag is wrong


def sig_verify(pk: bytes, msg: bytes, sig: bytes) -> bool:
    """Ed25519 verify. BUG: ignores bytes after 64 and 'fixes' S >= L with a compatibility shim."""
    r, s = sig[:32], int.from_bytes(sig[32:64], "little") % L  # non-canonical S silently reduced
    try:
        Ed25519PublicKey.from_public_bytes(pk).verify(r + s.to_bytes(32, "little"), msg)
        return True
    except InvalidSignature:
        return False


# ---- harness: the same loop works for any Wycheproof file of these types ----
def load(name: str) -> dict:
    return json.loads((VECTORS / name).read_text(encoding="utf-8"))


def aead_cases():
    for g in load("aes_gcm_subset.json")["testGroups"]:
        for t in g["tests"]:
            yield "aes_gcm_subset.json", t
    for t in load("derived_vectors.json")["aead"]:
        yield "derived_vectors.json", t


def eddsa_cases():
    for g in load("ed25519_subset.json")["testGroups"]:
        for t in g["tests"]:
            yield "ed25519_subset.json", {**t, "pk": g["publicKey"]["pk"]}
    pk = load("ed25519_subset.json")["testGroups"][0]["publicKey"]["pk"]  # derived from tcId 1 of that group
    for t in load("derived_vectors.json")["eddsa"]:
        yield "derived_vectors.json", {**t, "pk": pk}


def run(aead_open=aead_open, sig_verify=sig_verify) -> list:
    """Returns one row per test: (file, tcId, flags, expected, got). 'acceptable' would pass either way."""
    rows = []
    for f, t in aead_cases():
        h = {k: bytes.fromhex(t[k]) for k in ("key", "iv", "aad", "msg", "ct", "tag")}
        try:
            got = "valid" if aead_open(h["key"], h["iv"], h["ct"], h["tag"], h["aad"]) == h["msg"] else "wrong plaintext"
        except (InvalidTag, ValueError):  # a strict wrapper may refuse bad sizes with ValueError
            got = "invalid"
        rows.append((f, t["tcId"], t["flags"], t["result"], got))
    for f, t in eddsa_cases():
        ok = sig_verify(bytes.fromhex(t["pk"]), bytes.fromhex(t["msg"]), bytes.fromhex(t["sig"]))
        rows.append((f, t["tcId"], t["flags"], t["result"], "valid" if ok else "invalid"))
    return rows


def failures(rows) -> list:
    return [r for r in rows if r[3] != "acceptable" and r[3] != r[4]]


def report(rows) -> None:
    for f in dict.fromkeys(r[0] for r in rows):
        mine = [r for r in rows if r[0] == f]
        print(f"{f:<22} {len(mine) - len(failures(mine))}/{len(mine)} pass")
    for f, tc, flags, want, got in failures(rows):
        print(f"  FAIL tcId {tc} {flags}: expected {want}, wrapper said {got}")


if __name__ == "__main__":
    report(run())

"""Secrets in an application: load from a file (or env), keep out of repr, JSON logs, a log scanner,
and API-key rotation with a dual-validity window. The request handler below leaks a secret into a log (the fault)."""
import hashlib
import hmac
import io
import json
import logging
import os
import random
import re
import tempfile
from pathlib import Path

SEED = 16
SENSITIVE_KEY = re.compile(r"(?i)(password|passwd|secret|token|api[_-]?key|authorization|cookie)$")  # key names
PATTERNS = {"BEARER": re.compile(r"Bearer\s+[A-Za-z0-9._~+/-]{16,}=*"),
            "PRIVATE_KEY": re.compile(r"-----BEGIN [A-Z ]*PRIVATE KEY-----"),
            "URL_CREDENTIALS": re.compile(r"://[^/\s:@]+:[^/\s@]+@")}  # user:password@host


class Secret:
    """Holds a secret in a bytearray; repr/str never show it. Python may still keep other copies (see README)."""

    def __init__(self, value: str):
        self._buf = bytearray(value.encode())

    def reveal(self) -> str:
        return self._buf.decode()

    def wipe(self) -> None:
        self._buf[:] = bytes(len(self._buf))  # best effort: overwrites THIS buffer only

    def __repr__(self):
        return "Secret('***')"

    __str__ = __repr__


def load_secret(name: str, env=os.environ) -> Secret:
    """NAME_FILE (a mounted file, e.g. /run/secrets/...) wins over NAME (an env var, visible to child processes)."""
    if env.get(f"{name}_FILE"):
        return Secret(Path(env[f"{name}_FILE"]).read_text(encoding="utf-8").strip())
    if env.get(name):
        return Secret(env[name])
    raise KeyError(f"secret {name} not configured")  # fail closed: no default secret in code


class JsonFormatter(logging.Formatter):
    def format(self, record):  # one JSON object per line: easy to ship, query and scan
        return json.dumps({"level": record.levelname, "msg": record.getMessage(), **getattr(record, "ctx", {})}, sort_keys=True)


def json_logger(stream, name="orders") -> logging.Logger:
    log = logging.getLogger(name)
    log.handlers, log.propagate = [], False
    handler = logging.StreamHandler(stream)
    handler.setFormatter(JsonFormatter())
    log.addHandler(handler)
    log.setLevel(logging.DEBUG)
    return log


def handle_request(log, api_key: Secret, order_id: int, debug: bool) -> None:
    headers = {"Authorization": f"Bearer {api_key.reveal()}", "Accept": "application/json"}
    if debug:  # BUG on purpose: a debug line dumps the outgoing headers, Authorization included
        log.debug("upstream request", extra={"ctx": {"order": order_id, "headers": headers}})
    log.info("order sent", extra={"ctx": {"order": order_id, "status": 200}})


def scan_log(text: str, known=()) -> list:
    """Deterministic leak scanner: [(line_no, kind, detail)]. Tests and the agent-assist lab trust THIS, not a model."""
    found = []
    for n, line in enumerate(text.splitlines(), start=1):
        found += [(n, "KNOWN_SECRET", "value of a configured secret") for s in known if s and s in line]
        found += [(n, kind, "pattern") for kind, rx in PATTERNS.items() if rx.search(line)]
        for key, value in re.findall(r'"?([\w-]+)"?\s*[:=]\s*"?([^",}\s]+)', line):
            if SENSITIVE_KEY.search(key) and value not in ("[REDACTED]", "null", "") and not value.isdigit():
                found.append((n, "SENSITIVE_KEY", key))
    return sorted(set(found))


class ApiKeys:
    """Server side of a rotation: stores only SHA-256 hashes; the previous key works until grace_until."""

    def __init__(self, key: str):
        self.current, self.previous, self.grace_until = self._h(key), None, 0

    @staticmethod
    def _h(key: str) -> bytes:
        return hashlib.sha256(key.encode()).digest()

    def rotate(self, new_key: str, now: float, grace_s: float) -> None:
        self.previous, self.current, self.grace_until = self.current, self._h(new_key), now + grace_s

    def check(self, presented: str, now: float):
        h = self._h(presented)
        if hmac.compare_digest(h, self.current):  # constant-time compare of fixed-length hashes
            return "current"
        if self.previous and now <= self.grace_until and hmac.compare_digest(h, self.previous):
            return "previous"  # log this: when it drops to zero, clients have migrated
        return None


if __name__ == "__main__":
    rng = random.Random(SEED)
    with tempfile.TemporaryDirectory() as tmp:
        f = Path(tmp) / "orders_api_key"
        f.write_text("sk_demo_" + "".join(rng.choice("abcdef0123456789") for _ in range(32)) + "\n", encoding="utf-8")
        key = load_secret("ORDERS_API_KEY", env={"ORDERS_API_KEY_FILE": str(f)})
    print("loaded from file:", key, "| length", len(key.reveal()))
    buf = io.StringIO()
    log = json_logger(buf)
    debug_order = rng.randint(1, 5)  # seeded fault: the same request takes the debug path on every run
    for order in range(1, 6):
        handle_request(log, key, order, debug=order == debug_order)
    lines = buf.getvalue().splitlines()
    print(f"{len(lines)} JSON log lines, e.g. {lines[0]}")
    print("scanner findings:")
    for n, kind, detail in scan_log(buf.getvalue(), known=[key.reveal()]):
        print(f"  line {n}: {kind} ({detail})")
